code_of_record.cycles_from_decisions_verbatim:
def cycles_from_decisions(decisions: list) -> int:
    # Skip BOTH-effect (rolls). Worked examples: Aug 25 = 0, Aug 24 = 5.
    # Treating BOTH as CLOSING would count the Aug 25 roll as a cycle.
    cycles = 0
    prev = None
    for d in decisions:
        pe = str(d.get("effect") or "").upper()
        if pe == "BOTH":
            continue
        if pe == "CLOSING" and prev == "OPENING":
            cycles += 1
        if pe in ("OPENING", "CLOSING"):
            prev = pe
    return cycles

