def cycles_from_legs(legs: list) -> int:
    """Walk option legs in time order. Read ONLY position_effect.

    Count a cycle each time an OPENING is followed later by a CLOSING.
    Sort by (time, activity_id); activity_id breaks same-millisecond ties.
    do NOT reference put_call anywhere in this function.
    """
    def _sort_key(lg):
        aid = lg.get("activity_id")
        try:
            aid_n = int(aid) if aid is not None else 0
        except (TypeError, ValueError):
            aid_n = 0
        return (str(lg.get("time") or ""), aid_n)

    state = None
    count = 0
    for lg in sorted(legs or [], key=_sort_key):
        effect = "C" if lg.get("position_effect") == "CLOSING" else "O"
        if state == "O" and effect == "C":
            count += 1
        state = effect
    return count

schwab_intraday_count_cycles.verbatim:
def count_cycles(txs: list) -> int:
    unmatched = 0
    cycles = 0
    for t in txs:
        pe = str(t.get("position_effect") or "").upper()
        if pe == "OPENING":
            unmatched += 1
        elif pe == "CLOSING" and unmatched > 0:
            cycles += 1
            unmatched -= 1
    return cycles
